/* The id prop_set takes for item `id` (its tag in the top byte), or 0 when
 * the camera's code never writes it. */
static inline uint32_t nlr_prop_tag_of(uint16_t id)
{
    uint32_t lo = 0, hi = NLR_PROP_TAGS;
    while (lo < hi) {
        uint32_t mid = (lo + hi) / 2;
        if (nlr_prop_tags[mid].id == id)
            return (uint32_t)nlr_prop_tags[mid].tag << 24 | id;
        if (nlr_prop_tags[mid].id < id)
            lo = mid + 1;
        else
            hi = mid;
    }
    return 0;
}

static inline const char *nlr_prop_text(uint32_t offset)
{
    return offset < sizeof nlr_props_text ? nlr_props_text + offset : "";
}

/* The setting called `name`, or 0. The table is sorted by name. */
static inline const struct nlr_prop_name *nlr_prop_find(const char *name)
{
    uint32_t lo = 0, hi = NLR_PROP_NAMES;
    while (lo < hi) {
        uint32_t mid = (lo + hi) / 2;
        const unsigned char *a = (const unsigned char *)nlr_prop_text(nlr_prop_names[mid].name);
        const unsigned char *b = (const unsigned char *)name;
        while (*a && *a == *b) {
            a++;
            b++;
        }
        if (*a == *b)
            return &nlr_prop_names[mid];
        if (*a < *b)
            lo = mid + 1;
        else
            hi = mid;
    }
    return 0;
}

/* The id prop_set takes: the item with its type tag, or 0 for an item
 * the camera's menus never write (read it, watch it, do not set it). */
static inline uint32_t nlr_prop_tagged(const struct nlr_prop_name *p)
{
    return p && p->tag ? (uint32_t)p->tag << 24 | p->id : 0;
}

/* The label of `code` among the setting's choices, or 0. */
static inline const char *nlr_prop_choice_label(const struct nlr_prop_name *p, int32_t code)
{
    for (uint32_t n = 0; p && n < p->choice_count; n++)
        if (nlr_prop_choices[p->first_choice + n].code == code)
            return nlr_prop_text(nlr_prop_choices[p->first_choice + n].label);
    return 0;
}

